'use strict';
// Account UI: plain DOM and textContent only for user-controlled values.
// No private recordings, model data, session tokens or recovery codes are persisted
// in browser storage. Recovery codes exist in memory until this page is closed.
const q=id=>document.getElementById(id);
const params=new URLSearchParams(location.search);
const device=params.get('device');
const validDevice=typeof device==='string'&&/^[A-Z2-7]{10}$/.test(device);
const returnTo=validDevice?'/account/?device='+device:'/account/';
const state={config:null,dashboard:null,license:null,recoveryKit:null,pendingDeletionRequestId:null};
// An accessible, explicit Accept/Cancel dialog is required for deletion
// acknowledgments. Neither action triggers deletion: both are review stages.
function deletionConsentDialog(stage){
 const dialog=q('deletion-consent-modal');
 const accept=q('deletion-consent-accept');
 const cancel=q('deletion-consent-cancel');
 const scope=q('deletion-consent-scope');
 if(!dialog||!accept||!cancel||typeof dialog.showModal!=='function')
  throw new Error('Deletion consent dialog is unavailable in this browser.');
 scope.textContent=stage==='final'
  ?'Accept records your final, time-limited consent for an independently reviewed account deletion. It does not delete your account now.'
  :'Accept submits a request to review account deletion. It does not delete your account now.';
 return new Promise(resolve=>{
  dialog.returnValue='';
  const onAccept=()=>dialog.close('accept');
  const onCancel=()=>dialog.close('cancel');
  const onClose=()=>{
   accept.removeEventListener('click',onAccept);
   cancel.removeEventListener('click',onCancel);
   dialog.removeEventListener('close',onClose);
   resolve(dialog.returnValue==='accept');
  };
  accept.addEventListener('click',onAccept);
  cancel.addEventListener('click',onCancel);
  dialog.addEventListener('close',onClose);
  dialog.showModal();
  cancel.focus();
 });
}

for(const provider of ['google','apple']){
 const link=q(provider+'-login');
 link.addEventListener('click',async event=>{
  event.preventDefault();
  const error=q('age18-error');
  error.textContent='';
  if(!q('age18-confirm').checked){
   error.textContent='Confirm you are at least 18 before continuing.';
   q('age18-confirm').focus();
   return;
  }
  link.setAttribute('aria-disabled','true');
  try{
   await request('/eligibility/confirm',{method:'POST',
    data:{age18:true,policy_version:'age18-v1'}});
   location.assign(link.href);
  }catch(e){
   error.textContent=e.message||'Unable to confirm eligibility.';
   link.removeAttribute('aria-disabled');
  }
 });
}

const fmt=seconds=>{
 if(!Number.isFinite(Number(seconds))||Number(seconds)<=0)return '—';
 return new Intl.DateTimeFormat(undefined,{year:'numeric',month:'short',day:'numeric'}).format(new Date(Number(seconds)*1000));
};
async function request(path,{method='GET',data}={}){
 const response=await fetch('/api/account'+path,{
  method,credentials:'same-origin',cache:'no-store',
  headers:{'Accept':'application/json',...(method==='GET'?{}:{'Content-Type':'application/json'})},
  ...(method==='GET'?{}:{body:JSON.stringify(data??{})})
 });
 const result=await response.json().catch(()=>({}));
 if(!response.ok)throw Error(result.error||'The account service is temporarily unavailable.');
 return result;
}
function notice(text,error=false){
 const p=q('dashboard-notice');p.textContent=text;p.hidden=false;
 p.dataset.tone=error?'error':'info';
}
function accountMessage(status,title,description){
 q('account-state').textContent=status;q('account-title').textContent=title;q('account-message').textContent=description;
}
function downloadJson(filename,data){
 const blob=new Blob([JSON.stringify(data,null,2)+'\n'],{type:'application/json'});
 const url=URL.createObjectURL(blob);
 try{
  const anchor=document.createElement('a');
  anchor.href=url;anchor.download=filename;document.body.append(anchor);anchor.click();anchor.remove();
 }finally{setTimeout(()=>URL.revokeObjectURL(url),3000)}
}
function empty(message){
 const p=document.createElement('p');p.className='account-empty';p.textContent=message;return p;
}
// Device labels are generated by the app (e.g. "Mac · 876f52").
// Use a recognisable platform icon without inferring hardware identity.
function deviceIcon(name){
 const label=String(name||'').trim().toLowerCase();
 if(/^(mac(?:os|book)?|imac|apple)(?:$|[\s·-])/.test(label))return 'fa-brands fa-apple';
 if(/^(windows|win(?:dows)?|pc)(?:$|[\s·-])/.test(label))return 'fa-brands fa-windows';
 if(/^(linux|ubuntu|debian|fedora|arch)(?:$|[\s·-])/.test(label))return 'fa-brands fa-linux';
 return 'fa-solid fa-desktop';
}
function deviceRow(name,subline,actionLabel,onClick){
 const row=document.createElement('div');row.className='account-device';
 const identity=document.createElement('div');identity.className='account-device-identity';
 const badge=document.createElement('span');badge.className='account-device-icon';
 badge.setAttribute('aria-hidden','true');
 const glyph=document.createElement('i');glyph.className=deviceIcon(name);badge.append(glyph);
 const detail=document.createElement('div');detail.className='account-device-main';
 const label=document.createElement('strong');label.textContent=name;
 const metadata=document.createElement('small');metadata.textContent=subline;
 detail.append(label,metadata);identity.append(badge,detail);row.append(identity);
 if(actionLabel){
  const button=document.createElement('button');button.type='button';
  button.className='account-action account-action-outline';
  const icon=document.createElement('i');
  icon.className=actionLabel==='Sign out'?'fa-solid fa-arrow-right-from-bracket':'fa-solid fa-xmark';
  icon.setAttribute('aria-hidden','true');
  button.append(icon,document.createTextNode(actionLabel));
  button.setAttribute('aria-label',actionLabel+' '+name);
  button.addEventListener('click',async()=>{
   button.disabled=true;
   try{await onClick();}catch(error){notice(error.message,true)}finally{button.disabled=false}
  });
  row.append(button);
 }
 return row;
}
function renderPurchase(info,license){
 const purchase=info.purchase||{};
 const active=purchase.status==='active';
 const beta=!active&&license?.beta===true&&license?.lifetime===false;
 const label=active?'Pro · Lifetime':beta?'Pro · Beta':'Free';
 const details={
  active:'Lifetime Pro license on file',
  refunded:'Refunded',
  void:'Cancelled',
  none:'No purchase on file'
 };
 q('purchase-badge').textContent=active?'Lifetime Pro':beta?'Temporary beta Pro':purchase.status==='refunded'?'Refunded':purchase.status==='void'?'Cancelled':'Free edition';
 q('purchase-name').textContent=active?'Humperdinck Pro':beta?'Humperdinck Pro Beta':'Humperdinck Free';
 q('purchase-message').textContent=active?
  'Your lifetime Pro entitlement is associated with this account. There are no renewals or mandatory online checks for an installed signed license.':
  beta?'Your temporary beta Pro access expires '+fmt(license.expires_at)+'. It is not a purchase or a lifetime license; connect your desktop account and activate Pro to start testing.':
  purchase.status==='refunded'||purchase.status==='void'?
  'No active Pro entitlement is associated with this account. Previously exported offline licenses cannot be remotely revoked.':
  'Your Free studios, built-in voices and exports remain available without signing in or entering payment details.';
 q('purchase-status').textContent=beta?'Temporary beta access':details[purchase.status]||'Not available';
 q('purchase-date').textContent=active?fmt(purchase.issued_at):'—';
 q('purchase-provider').textContent=purchase.provider==='stripe-managed-test'?'Stripe (refunded test purchase)':purchase.provider||'Not connected';
 q('purchase-reference').textContent=purchase.reference||'—';
 q('purchase-reference').title=purchase.reference||'';
 q('stat-edition').textContent=label;
 q('stat-edition-note').textContent=active?'Permanent Pro access':beta?'Expires '+fmt(license.expires_at):'Your local studio';
 q('purchase-footnote').textContent=active?
  'Purchases are one-time; payment receipts will be linked here when the checkout provider is integrated.':beta?
  'Beta testing access expires automatically. No payment is charged and no lifetime license backup is available.':
  'One-time Pro checkout is not available yet. No payment has been charged through this dashboard.';
 const proDevices=Array.isArray(license?.devices)?license.devices:[];
 const count=Number(license?.active_devices||0),limit=Number(license?.device_limit||10);
 q('stat-pro-seats').textContent=active?count+' / '+limit:'0 / 10';
 q('pro-count').textContent=active?count+' / '+limit:'0 / 10';
 const list=q('pro-list');list.replaceChildren();
 if(!active||!proDevices.length)list.append(empty(active?'No Pro activations yet. Activate Pro in your desktop app.':'Pro activations appear after a verified lifetime purchase.'));
 for(const item of proDevices){
  const name=item.label||'Humperdinck installation';
  list.append(deviceRow(name,(item.active?'Active':'Deactivated')+' · Registered '+fmt(item.activated_at),
   item.active?'Deactivate':null,async()=>{
    if(!confirm('Deactivate this online Pro slot? An offline license already exported to this computer remains valid.'))return;
    await request('/license/devices/'+encodeURIComponent(item.id)+'/deactivate',{method:'POST'});
    notice('Online Pro slot released. Offline license files are unaffected.');
    await refresh();
   }));
 }
 const canDownload=active&&Boolean(license?.license?.backup_available);
 q('download-license').hidden=!canDownload;
 q('license-title').textContent=active?'Your signed lifetime Pro license':beta?'Your temporary Pro trial':'Your Free edition needs no license';
 q('license-description').textContent=active?
  'Export your permanent Pro license as a signed JSON backup. You can restore it from the desktop app without an internet connection.':
  beta?'Sign in from your desktop app and choose Activate Pro. Temporary beta certificates are bound to that installation, expire automatically, and cannot be backed up as lifetime licenses.':
  'All Free features work without a license file or an internet connection.';
 q('license-missing').textContent=active&&!canDownload?'License download is temporarily unavailable. Your installed offline backup remains valid.':beta?
  'Beta Pro is temporary; export of a permanent offline license is unavailable.':
  'Pro license downloads become available after a verified purchase.';
 q('license-missing').hidden=canDownload;
}
function renderConnections(info){
 const connected=Array.isArray(info.connected_desktops)?info.connected_desktops:[];
 const older=Number(info.older_desktop_sessions||0);
 const total=connected.length+older;
 q('stat-connected').textContent=String(total);
 q('connected-count').textContent=total+' connected';
 const list=q('connected-list');list.replaceChildren();
 if(!connected.length&&!older)list.append(empty('No connected desktop sessions. Sign in from the desktop app to connect a computer.'));
 for(const item of connected){
  list.append(deviceRow(item.label||'Humperdinck desktop','Connected '+fmt(item.connected_at)+' · Expires '+fmt(item.expires_at),
   'Sign out',async()=>{
    if(!confirm('Sign this computer out of its online account? Saved offline Pro licenses and local projects will stay on it.'))return;
    await request('/dashboard/connections/'+encodeURIComponent(item.id)+'/revoke',{method:'POST'});
    notice('Desktop session signed out remotely.');
    await refresh();
   }));
 }
 q('legacy-notice').hidden=older===0;
 q('legacy-notice').textContent=older+' older session'+(older===1?'':'s')+' cannot be named individually. Use “Sign out all desktops” to revoke them.';
 q('disconnect-all').hidden=total===0;
}
function renderRecovery(info){
 const recovery=info.recovery||{};
 const number=Number(recovery.codes_remaining||0);
 q('stat-recovery').textContent=number+' / 8';
 q('recovery-status').textContent=number?
  number+' unused recovery code'+(number===1?'':'s')+' available.':
  'No recovery codes saved yet. Generate a kit before you need one.';
 const providers=Array.isArray(info.account?.providers)?info.account.providers:[];
 const providerDisplay=q('linked-providers');
 providerDisplay.replaceChildren();
 if(!providers.length){providerDisplay.textContent='No linked provider'}
 else for(const provider of providers){
  const name=provider==='google'?'Google':provider==='apple'?'Apple':String(provider);
  const item=document.createElement('span');item.className='linked-provider';
  const icon=document.createElement('i');icon.setAttribute('aria-hidden','true');
  icon.className=provider==='google'?'fa-brands fa-google':provider==='apple'?'fa-brands fa-apple':'fa-solid fa-user-shield';
  item.append(icon,document.createTextNode(name));providerDisplay.append(item);
 }
 q('identity-summary').textContent=providers.length?
  'Linked sign-in: '+providers.map(p=>p==='google'?'Google':p==='apple'?'Apple':p).join(', ')+'. You can link an additional provider using a signed-in session.':
  'No linked sign-in provider. Add one while you can access this dashboard.';
 q('link-google').hidden=!state.config?.providers?.google;
 q('link-apple').hidden=!state.config?.providers?.apple;
}
// Stripe Testing checkout is offered only when the server confirms this
// signed-in web account is on its private testing allowlist. No public Buy Pro.
async function renderTestCheckout(active){
 const box=q('test-checkout-box');
 box.hidden=true;
 if(active||state.dashboard?.purchase?.checkout_available)return;
 try{
  const response=await fetch('/api/commerce/sandbox/status',{
   credentials:'same-origin',cache:'no-store',headers:{'Accept':'application/json'}
  });
  if(!response.ok)return;
  const status=await response.json();
  if(status.mode!=='test')return;
  q('test-checkout-note').textContent=
   'Stripe Testing only — $49.00 one-time Humperdinck Pro. Use Stripe test card 4242 4242 4242 4242, a future expiry and any CVC. No real money is charged.';
  box.hidden=false;
 }catch{}
}
function renderLiveCheckout(account){
 const ready=account.purchase?.checkout_available===true&&account.purchase?.status!=='active';
 q('live-checkout-box').hidden=!ready;
 if(ready)q('purchase-footnote').textContent='Secure $49 one-time Pro checkout is available. Taxes calculated by Stripe. No recurring subscription.';
}
async function startLiveCheckout(){
 const button=q('live-checkout');button.disabled=true;
 try{
  const response=await fetch('/api/commerce/stripe/checkout',{
   method:'POST',credentials:'same-origin',cache:'no-store',
   headers:{'Accept':'application/json'}
  });
  const result=await response.json().catch(()=>({}));
  if(!response.ok)throw Error(result.error||'Stripe checkout is unavailable.');
  const target=new URL(result.checkout_url);
  if(target.protocol!=='https:'||target.hostname!=='checkout.stripe.com')
   throw Error('Unexpected checkout provider.');
  location.assign(target.href);
 }catch(error){notice(error.message,true);button.disabled=false;}
}
async function startTestCheckout(){
 const button=q('test-checkout');button.disabled=true;
 try{
  // The sandbox endpoint intentionally accepts no request body. Keep the
  // checkout in this tab to avoid browser pop-up blockers.
  const response=await fetch('/api/commerce/sandbox/checkout',{
   method:'POST',credentials:'same-origin',cache:'no-store',
   headers:{'Accept':'application/json'}
  });
  const result=await response.json().catch(()=>({}));
  if(!response.ok)throw Error(result.error||'Stripe test checkout is unavailable.');
  const target=new URL(result.checkout_url);
  if(target.protocol!=='https:'||target.hostname!=='checkout.stripe.com')
   throw Error('Unexpected Stripe checkout address.');
  location.assign(target.href);
 }catch(error){notice(error.message,true);button.disabled=false;}
}
// The Stripe webhook can arrive after Checkout redirects to the account.
async function awaitTestPurchase(){
 if(params.get('stripe')!=='return')return;
 history.replaceState(null,'',location.pathname+location.hash);
 notice('Checking your Stripe purchase and Pro activation…');
 for(let i=0;i<10;i++){
  try{await refresh()}catch{}
  if(state.dashboard?.purchase?.status==='active'){
   notice('Stripe purchase verified: Pro is active on this account. Activate the existing purchase from My Account in the desktop app.');
   return;
  }
  await new Promise(resolve=>setTimeout(resolve,3000));
 }
 notice('The Stripe checkout returned, but Pro activation has not been confirmed. We need to inspect webhook delivery before trying again.',true);
}
async function refresh(){
 const [account,license]=await Promise.all([request('/dashboard'),request('/license')]);
 state.dashboard=account;state.license=license;
 renderTestCheckout(account.purchase?.status==='active');
 const profile=account.account||{};
 q('welcome-account').textContent=profile.email||profile.display_name||'Signed in securely';
 q('account-display-name').textContent=profile.display_name||'Humperdinck account';
 q('account-display-email').textContent=profile.email||'Private email';
 q('account-id-value').textContent=profile.id||'—';
 renderPurchase(account,license);
 renderLiveCheckout(account);
 renderConnections(account);
 renderRecovery(account);
}

async function refreshOwnerAnalytics(){
 const status=q('analytics-status');
 if(!status)return;
 status.textContent='Refreshing analytics…';
 try{
  const days=q('analytics-range').value;
  const info=await request('/dashboard/analytics?days='+encodeURIComponent(days));
  q('owner-analytics').hidden=false;
  q('owner-analytics-link').hidden=false;
  try { q('analytics-exclude-self').checked=localStorage.getItem('humperdinck_analytics_exclude')==='1'; } catch {}
  const display=x=>Number.isFinite(Number(x))?Number(x).toLocaleString():'—';
  const events=info.events||{},github=info.github||{};
  q('analytics-views').textContent=events.available?display(events.page_views):'—';
  const clicks=events.download_clicks||{};
  q('analytics-clicks').textContent=events.available?display(Object.values(clicks).reduce((a,b)=>a+Number(b||0),0)):'—';
  for(const platform of ['windows','macos','linux']){
   q('analytics-click-'+platform).textContent=events.available?display(clicks[platform]):'—';
   q('analytics-download-'+platform).textContent=github.available?display(github.counts?.[platform]):'—';
  }
  q('analytics-downloads').textContent=github.available?display(Object.values(github.counts||{}).reduce((a,b)=>a+Number(b||0),0)):'—';
  const accounts=info.accounts||{};
  q('analytics-accounts-active').textContent=accounts.available?display(accounts.active):'—';
  q('analytics-accounts-detail').textContent=accounts.available?`${display(accounts.total)} total · ${display(accounts.new_accounts)} new`:'—';
  const providerName=p=>({google:'Google',apple:'Apple',github:'GitHub',microsoft:'Microsoft',email:'Email'}[p]||p);
  q('analytics-accounts-providers').textContent=accounts.available?Object.entries(accounts.providers||{})
   .map(([p,c])=>`${providerName(p)} ${display(c.active)} active / ${display(c.total)}`).join(' · '):'';
  const messages=[];
  if(!accounts.available)messages.push('Accounts: '+(accounts.reason||'unavailable'));
  if(!events.available)messages.push('Cloudflare events: '+(events.reason||'unavailable'));
  if(!github.available)messages.push('GitHub download counts: '+(github.reason||'unavailable'));
  status.textContent=messages.length?messages.join(' · '):'Live aggregate counts loaded. GitHub totals cover published assets, all time.';
 }catch(error){
  // The owner-only route returns 404 for everyone else: never show an admin panel.
  if(/Not found|Sign in required/.test(error.message)){
   q('owner-analytics').hidden=true;q('owner-analytics-link').hidden=true;
  }else{
   status.textContent='Analytics unavailable: '+error.message;
  }
 }
}

async function load(){
 try{
  state.config=await request('/config');
  if(!state.config?.available)throw Error('Account service is not configured');
 }catch(error){
  accountMessage('Unavailable','Account sign-in unavailable',
   'The account service cannot be reached. Humperdinck Free still works offline.');
  q('recover-toggle').hidden=true;return;
 }
 try{
  const me=await request('/me');
  if(me.authenticated){
   q('account-gate').hidden=true;
   q('dashboard').hidden=false;
   if(validDevice){
    q('pairing').hidden=false;
    q('device-code').textContent=device.slice(0,5)+'-'+device.slice(5);
    // The desktop app waits on this one click; make it the first thing seen.
    document.title='Approve Humperdinck desktop sign-in';
    q('pairing').scrollIntoView({block:'center'});
    q('approve').focus({preventScroll:true});
   }
   try{await refresh()}catch(error){notice('Account dashboard could not load: '+error.message,true)}
   await refreshOwnerAnalytics();
   if(params.get('recovered')==='1')notice('Recovery code accepted. Link another sign-in method and generate a fresh recovery kit.');
   awaitTestPurchase();
   return;
  }
  accountMessage('Sign in','Your Humperdinck account',
   'Access your purchases, connected computers, license backups and recovery settings.');
  const configured=Object.values(state.config.providers||{}).some(Boolean);
  q('providers').hidden=!configured;
  q('age-attestation').hidden=!configured;
  for(const provider of ['google','apple']){
   const link=q(provider+'-login');
   link.hidden=!state.config.providers?.[provider];
   link.href='/api/account/start/'+provider+'?return_to='+encodeURIComponent(returnTo);
  }
  q('recover-toggle').hidden=false;
  if(params.get('error')){
   const expired=params.get('error')==='signin_expired';
   accountMessage('Sign-in issue',expired?'Your sign-in could not be completed':'Please try again',
    expired?'The secure sign-in attempt expired or was interrupted. Select Google or Apple below to start a fresh sign-in.':
    'The identity provider could not complete sign-in. Please try again or use a saved recovery code.');
  }
 }catch(error){
  accountMessage('Unavailable','Cannot load account','Please try again. Your local Humperdinck Free studios still work without sign-in.');
 }
}
q('recover-toggle').addEventListener('click',()=>{
 const form=q('recovery-login');form.hidden=!form.hidden;
 q('recover-toggle').setAttribute('aria-expanded',String(!form.hidden));
 if(!form.hidden)q('recover-account-id').focus();
});
q('recovery-login').addEventListener('submit',async event=>{
 event.preventDefault();
 const button=event.currentTarget.querySelector('button[type="submit"]');
 button.disabled=true;
 q('recover-result').textContent='Checking your one-time code…';
 try{
  const result=await request('/recovery/redeem',{method:'POST',data:{
   account_id:q('recover-account-id').value.trim(),code:q('recover-code').value.trim()}});
  if(!result.recovered)throw Error('Recovery was not completed');
  q('recover-code').value='';
  location.replace('/account/?recovered=1');
 }catch(error){q('recover-result').textContent=error.message;button.disabled=false}
});
q('test-checkout').addEventListener('click',startTestCheckout);
q('live-checkout').addEventListener('click',startLiveCheckout);
q('logout').addEventListener('click',async()=>{
 const button=q('logout');button.disabled=true;
 try{await request('/logout',{method:'POST'});location.assign('/account/')}
 catch(error){notice(error.message,true);button.disabled=false}
});
q('approve').addEventListener('click',async()=>{
 if(!validDevice)return;
 const button=q('approve');button.disabled=true;
 q('pair-result').textContent='Connecting…';
 try{
  await request('/device/approve',{method:'POST',data:{code:device}});
  q('pair-result').textContent='Approved. Return to Humperdinck: it finishes signing in within a few seconds. You can close this tab.';
  button.hidden=true;
  q('pairing').classList.add('approved');
  history.replaceState(null,'','/account/');
 }catch(error){q('pair-result').textContent=error.message;button.disabled=false}
});
q('disconnect-all').addEventListener('click',async()=>{
 if(!confirm('Sign out every desktop session connected to this account? Offline Pro licenses and local files will continue to work.'))return;
 const button=q('disconnect-all');button.disabled=true;
 try{
  const result=await request('/dashboard/connections/revoke-all',{method:'POST'});
  notice('Signed out '+result.revoked+' desktop session'+(result.revoked===1?'':'s')+'.');
  await refresh();
 }catch(error){notice(error.message,true)}finally{button.disabled=false}
});
q('download-account-data').addEventListener('click',async()=>{
 const button=q('download-account-data');button.disabled=true;
 try{
  const exported=await request('/privacy/export');
  if(exported.format!=='humperdinck-account-data-export-v1')throw Error('Account export is unavailable.');
  downloadJson('humperdinck-account-export.json',exported);
  notice('Account information exported. Keep the file private.');
 }catch(error){notice('Export unavailable: '+error.message+' You may contact privacy@humperdinck.studio.',true)}
 finally{button.disabled=false}
});
q('submit-privacy-request').addEventListener('click',async()=>{
 const kind=q('privacy-request-kind').value;
 if(!['access','correction','deletion'].includes(kind))return;
 if(kind==='deletion'){
  if(!await deletionConsentDialog('review'))return;
 }else if(!confirm('Submit your '+kind+' request for manual review?'))return;
 const button=q('submit-privacy-request');button.disabled=true;
 try{
  const record=await request('/privacy/requests',{
   method:'POST',data:{kind,confirmation:'REQUEST PRIVACY REVIEW',
    ...(kind==='deletion'?{
     forfeitureAcknowledgment:'I UNDERSTAND ACCOUNT DELETION MAY FORFEIT PRO',
     offlineCertificateAcknowledged:true
    }:{})}
  });
  if(record.status!=='pending'||!record.request_id)throw Error('Privacy request was not recorded.');
  q('privacy-request-status').textContent=
   'Request '+record.request_id+' is pending review.'+(record.duplicate?' An existing request was found.':'');
  if(kind==='deletion'){
   state.pendingDeletionRequestId=record.request_id;
   q('deletion-final-confirmation').hidden=!state.config?.deletion_confirmation_enabled;
  }
  notice('Privacy request recorded for manual review. Your Pro license has not changed.');
 }catch(error){
  q('privacy-request-status').textContent='Request unavailable. Contact privacy@humperdinck.studio.';
  notice(error.message,true);
 }finally{button.disabled=false}
});
q('submit-deletion-final').addEventListener('click',async()=>{
 const message=q('deletion-final-status'),button=q('submit-deletion-final');
 if(!state.config?.deletion_confirmation_enabled||!state.pendingDeletionRequestId){
  message.textContent='Final deletion confirmation is not available.';return;
 }
 if(q('deletion-confirm-phrase').value.trim()!=='DELETE MY HUMPERDINCK ACCOUNT'||
   !q('deletion-forfeiture').checked||!q('deletion-offline').checked){
  message.textContent='Type the exact phrase and acknowledge both consequences.';return;
 }
 if(!await deletionConsentDialog('final'))return;
 button.disabled=true;
 try{
  const result=await request('/privacy/deletion/final-confirm',{
   method:'POST',data:{requestId:state.pendingDeletionRequestId,
    policyVersion:'deletion-draft-v1',confirmation:'DELETE MY HUMPERDINCK ACCOUNT',
    forfeitureAcknowledged:true,offlineCertificatesAcknowledged:true}
  });
  message.textContent=result.status==='confirmed-for-review'
   ?'Final confirmation recorded. No account or license has been deleted. A verified operator review is still required.'
   :'Confirmation could not be recorded.';
 }catch(error){message.textContent='Final confirmation unavailable: '+error.message}
 finally{button.disabled=false}
});
q('download-license').addEventListener('click',async()=>{
 const button=q('download-license');button.disabled=true;
 try{
  const backup=await request('/license/backup');
  downloadJson('humperdinck-pro-license.json',{format:backup.format,license:backup.license});
  notice('Permanent offline license backup downloaded. Store it securely.');
 }catch(error){notice(error.message,true)}finally{button.disabled=false}
});
q('generate-recovery').addEventListener('click',async()=>{
 if(!confirm('Generate eight new one-time recovery codes? All previously saved unused codes will stop working.'))return;
 const button=q('generate-recovery');button.disabled=true;
 try{
  const kit=await request('/dashboard/recovery/codes',{method:'POST'});
  if(!Array.isArray(kit.codes)||kit.codes.length!==8)throw Error('Recovery kit was not returned');
  state.recoveryKit=kit;
  const grid=q('recovery-codes');grid.replaceChildren();
  for(const code of kit.codes){
   const item=document.createElement('span');item.textContent=code;grid.append(item);
  }
  q('recovery-kit').hidden=false;
  notice('Eight codes created. Download your kit now; these codes will not be shown again.');
  await refresh();
 }catch(error){notice(error.message,true)}finally{button.disabled=false}
});
q('download-recovery').addEventListener('click',()=>{
 if(!state.recoveryKit){notice('Generate recovery codes first.',true);return}
 downloadJson('humperdinck-account-recovery.json',state.recoveryKit);
 notice('Recovery kit downloaded. Anyone holding this file can recover your account; protect it like a password.');
});
q('analytics-exclude-self').addEventListener('change',event=>{
 try{
  if(event.target.checked)localStorage.setItem('humperdinck_analytics_exclude','1');
  else localStorage.removeItem('humperdinck_analytics_exclude');
 }catch{
  event.target.checked=false;
  q('analytics-status').textContent='Browser storage is disabled; exclusion could not be saved.';
 }
});
q('analytics-refresh').addEventListener('click',refreshOwnerAnalytics);
q('analytics-range').addEventListener('change',refreshOwnerAnalytics);
load();
